/* Which test series feeds a given input slot. Price groups are already
* flattened to one slot per component. */
typedef enum {
   TA_VIN_REAL = 0,
   TA_VIN_OPEN,
   TA_VIN_HIGH,
   TA_VIN_LOW,
   TA_VIN_CLOSE,
   TA_VIN_VOLUME,
   TA_VIN_OPENINTEREST,
   TA_VIN_PERIODS      /* MAVP's per-element period series */
} TA_VInputKind;

/* An enum parameter's domain is its MEMBER LIST, not the numeric span the
 * other two kinds carry: sampling min/max/interior would silently stop
 * probing a member the moment one is appended past it. */
typedef enum {
   TA_VOPT_INT,
   TA_VOPT_REAL,
   TA_VOPT_ENUM
} TA_VOptKind;

/* Members of the widest enum any optional parameter uses, from enums.yaml. */
#define TA_V_MAX_ENUM_MEMBERS 13

/* Concrete (never-sentinel) bounds for one optional parameter. */
typedef struct {
   const char *name;
   TA_VOptKind kind;
   double minValue;
   double maxValue;   /* TA_VOPT_ENUM: the highest member value */
   double defValue;
} TA_VOptSpec;

typedef TA_RetCode (*TA_VFrameD)( int startIdx, int endIdx,
                  const double *const in[], const double optIn[],
                  int *outBegIdx, int *outNBElement,
                  double *const outReal[], int *const outInteger[] );
typedef TA_RetCode (*TA_VFrameS)( int startIdx, int endIdx,
                  const float *const in[], const double optIn[],
                  int *outBegIdx, int *outNBElement,
                  double *const outReal[], int *const outInteger[] );

typedef struct {
   const char          *name;         /* without the TA_ prefix */
   TA_VFrameD           guarded;      /* TA_<N>                */
   TA_VFrameS           single;       /* TA_S_<N>              */
   int                  nbInput;      /* flattened array parameters */
   const TA_VInputKind *inputKind;
   int                  nbOptInput;
   const TA_VOptSpec   *optInput;     /* NULL when nbOptInput == 0 */
   int                  nbOutput;
   /* Per output, indexed by declaration position: 1 = TA_Integer.
    * A function may mix the two (SYNTH12), so this cannot collapse
    * to one flag; the thunks subscript outReal[]/outInteger[] by
    * that same declaration position, leaving a hole in whichever
    * array the slot does not belong to. */
   const int           *outIsInt;
   /* 1 when the guarded body delegates to a shared TA_<N>_Private
    * rather than holding the algorithm inline. Derived from the
    * definition having an explicit <name>_private() in
    * ta_codegen/input/, so it can never go stale against a
    * hand-maintained list. */
   int                  delegatesToPrivate;
} TA_VariantEntry;

